dir:


































  &DefaultButton;




function dir$dmxd(p){
  this.constructor(p);
}
dir$dmxd.prototype = new DirEvent();
dir$dmxd.prototype.afterInit = function(){
  var p = this._dir;
}
dir$dmxd.prototype.afterInit = function(renderType){
  var p = this._dir,g = p.grid()

dir$dmxdDisabledMasterField(p, g);

}

function dir$dmxdDisabledMasterField(p, g){

  if(p.valForm('ma_xd').trim() != '')
  {
    p.setDisabled('ma_xd', true);
  }
  else
  {
    p.setDisabled('ma_xd', false);
  }
}






	.control-label.ma_xd, .control-label.ten_xd
	{	

		color: #499b98;;
	}







declare @codeExistsNewMsg nvarchar(256), @codeExistsEditMsg nvarchar(256)
select @codeExistsNewMsg = case when '@@lan' = 'v' then N'Mã xăng dầu đã tồn tại' else N'Petroleum code is exists' end
select @codeExistsEditMsg = case when '@@lan' = 'v' then N'Mã xăng dầu đã tồn tại' else N'Petroleum code is exists' end
